package binding

import (
	"bytes"
	"mime/multipart"
	"net/http"
	"testing"
)

func TestTmpNonMandatoryFileBinding(t *testing.T) {
	type BindFile struct {
		Name  string                `form:"name" binding:"required"`
		Email string                `form:"email" binding:"required"`
		File  *multipart.FileHeader `form:"file"`
	}
	var body bytes.Buffer
	mw := multipart.NewWriter(&body)
	mw.WriteField("name", "testname")
	mw.WriteField("email", "test@example.com")
	// file part with empty filename (file not selected in browser)
	fw, _ := mw.CreateFormFile("file", "")
	fw.Write([]byte{})
	mw.Close()

	req, err := http.NewRequest("POST", "/upload", &body)
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("Content-Type", MIMEMultipartPOSTForm+"; boundary="+mw.Boundary())

	var f BindFile
	if err := FormMultipart.Bind(req, &f); err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	if f.File != nil {
		t.Fatalf("expected nil file, got %+v", f.File)
	}
	if f.Name != "testname" || f.Email != "test@example.com" {
		t.Fatalf("wrong fields: %+v", f)
	}
}
